"""Independent, deliberately naive reference model for the cache-group protocol."""
import json, math, subprocess, functools, os

DUMP = '/workspace/dev/dump'
CACHE = {}

class Invalid(Exception):
    pass

def pairs(items):
    obj = {}
    for k, v in items:
        if k in obj:
            raise Invalid('dup')
        obj[k] = v
    return obj

def bad_constant(s):
    raise Invalid('nonfinite')

def finite(s):
    x = float(s)
    if not math.isfinite(x):
        raise Invalid('nonfinite')
    return x

def parse(text):
    if text.startswith('\ufeff'):
        raise Invalid('bom')
    try:
        return json.loads(text, object_pairs_hook=pairs, parse_constant=bad_constant, parse_float=finite)
    except Invalid:
        raise
    except (ValueError, TypeError, RecursionError, OverflowError):
        raise Invalid('json')

def topo_table(code, args):
    key = (code, tuple(args))
    if key not in CACHE:
        out = subprocess.run([DUMP, str(code)] + [str(a) for a in args] + ['0'] * (7 - len(args)),
                             capture_output=True, check=True).stdout.decode().splitlines()
        n, t = map(int, out[0].split('\t'))
        assert len(out) == 2 + t, (len(out), t)
        foots = []
        doms = []
        for line in out[2:]:
            src, dst, fp = line.split('\t')
            foots.append(frozenset(int(x) for x in fp.split() if x != ''))
            doms.append((int(src), int(dst)))
        CACHE[key] = (n, t, foots, doms)
    return CACHE[key]

# ---------------------------------------------------------------- validation
def valid_topology(t):
    if not isinstance(t, list) or not t or not isinstance(t[0], str):
        raise Invalid('topology shape')
    mode = t[0]
    def I(x, lo, hi):
        if type(x) is not int or not (lo <= x <= hi):
            raise Invalid('topology range')
        return x
    if mode == 'clos':
        if len(t) != 4: raise Invalid('clos')
        k = I(t[1], 4, 18)
        if k % 2: raise Invalid('clos k')
        if t[2] not in ('tor', 'pod'): raise Invalid('clos scope')
        intra = I(t[3], 0, 1)
        n = k * k; tors = n // 2
        templates = tors * (tors - 1 if intra else tors - k // 2)
        return 0, [k, 1 if t[2] == 'pod' else 0, intra], n, templates
    if mode == 'leaf-spine':
        if len(t) != 3: raise Invalid('ls')
        leaves = I(t[1], 2, 256); spines = I(t[2], 1, 256)
        return 1, [leaves, spines], leaves + spines, leaves * (leaves - 1)
    if mode in ('torus2d', 'torus3d'):
        if len(t) != 3: raise Invalid('tor')
        side = I(t[1], 3, 18)
        want = 'row' if mode == 'torus2d' else 'line'
        if t[2] not in ('host', want): raise Invalid('tor scope')
        n = side ** (2 if mode == 'torus2d' else 3)
        return (2 if mode == 'torus2d' else 3), [side, 0 if t[2] == 'host' else 1], n, n * (n - 1)
    if mode == 'dragonfly':
        if len(t) != 5: raise Invalid('df')
        g = I(t[1], 1, 64); a = I(t[2], 1, 64); h = I(t[3], 1, 64)
        if g < 2 or g - 1 != a * h: raise Invalid('df params')
        if t[4] not in ('router', 'group', 'target'): raise Invalid('df scope')
        n = g * a
        return 4, [g, a, h, ['router', 'group', 'target'].index(t[4])], n, n * (n - 1)
    if mode == 'dragonfly-plus':
        if len(t) != 7: raise Invalid('df+')
        g = I(t[1], 1, 64); l = I(t[2], 1, 64); s = I(t[3], 1, 64); h = I(t[4], 1, 64)
        dense = I(t[5], 0, 1)
        if g < 2 or (not dense and g - 1 != s * h): raise Invalid('df+ params')
        if t[6] not in ('tor', 'group'): raise Invalid('df+ scope')
        n = g * (l + s); endpoints = g * l
        return 5, [g, l, s, h, dense, 1 if t[6] == 'group' else 0], n, endpoints * (endpoints - 1)
    raise Invalid('unknown topology')

def check(cond):
    if not cond:
        raise Invalid('schema')

def validate(request):
    check(isinstance(request, dict) and set(request) == {'version', 'sessions'})
    check(type(request['version']) is int and request['version'] == 2)
    sessions = request['sessions']
    check(isinstance(sessions, list) and len(sessions) <= 16)
    work = tasks_total = edits_total = queries_total = tx_total = 0
    out = []
    for s in sessions:
        check(isinstance(s, dict) and set(s) == {'topology', 'caps', 'groups', 'tasks', 'query', 'transactions'})
        code, args, n, tcount = valid_topology(s['topology'])
        check(n <= 343)
        groups = s['groups']
        check(isinstance(groups, list) and 0 < len(groups) <= 8192)
        g = len(groups)
        tasks = s['tasks']
        check(isinstance(tasks, list) and len(tasks) <= 100000)
        d = len(tasks)
        caps = s['caps']
        check(isinstance(caps, list) and len(caps) == n)
        for c in caps:
            check(type(c) is int and 0 <= c <= 10 ** 9)
        grows = []
        for row in groups:
            check(isinstance(row, list) and len(row) == 2)
            check(type(row[0]) is int and 0 <= row[0] <= 64)
            check(type(row[1]) is int and 1 <= row[1] <= 10 ** 12)
            grows.append((row[0], row[1]))
        trows = []
        for row in tasks:
            check(isinstance(row, list) and len(row) == 5)
            for x, lo, hi in zip(row, [0, 0, 1, 0, 0], [tcount - 1, g - 1, 10 ** 9, 10 ** 9, 1]):
                check(type(x) is int and lo <= x <= hi)
            trows.append(tuple(row))
        q = query(s['query'], g, n, d)
        txs = s['transactions']
        check(isinstance(txs, list) and len(txs) <= 50000)
        tx_total += len(txs)
        ops = 0
        bout = []
        for tx in txs:
            check(isinstance(tx, dict) and set(tx) == {'revision', 'edits', 'query'})
            check(type(tx['revision']) is int and 0 <= tx['revision'] <= 10 ** 9)
            edits = tx['edits']
            check(isinstance(edits, list) and len(edits) <= 100000)
            ops += len(edits)
            elist = []
            for e in edits:
                check(isinstance(e, list) and len(e) == 3 and isinstance(e[0], str))
                op, idx, value = e
                names = {'move': (0, g - 1), 'weight': (1, 10 ** 9), 'class': (0, 10 ** 9),
                         'bind': (0, tcount - 1), 'pin': (0, 1), 'quota': (0, 64),
                         'budget': (1, 10 ** 12), 'cap': (0, 10 ** 9)}
                check(op in names)
                idcap = d if op in ('move', 'weight', 'class', 'bind', 'pin') else (g if op in ('quota', 'budget') else n)
                check(type(idx) is int and 0 <= idx <= idcap - 1)
                lo, hi = names[op]
                check(type(value) is int and lo <= value <= hi)
                elist.append((op, idx, value))
            bq = query(tx['query'], g, n, d)
            bout.append((tx['revision'], elist, bq))
        tasks_total += d
        edits_total += ops
        work += (tcount + d + ops) * n
        out.append((code, args, n, tcount, caps, grows, trows, q, bout))
    work += 8 * queries_total
    check(work <= 128000000)
    check(tasks_total <= 200000 and edits_total <= 100000 and tx_total <= 50000)
    return out

def query(q, g, n, d):
    check(isinstance(q, dict) and set(q) == {'groups', 'nodes', 'tasks'})
    res = []
    for key, cap in (('groups', g), ('nodes', n), ('tasks', d)):
        lst = q[key]
        check(isinstance(lst, list) and len(lst) <= 200000)
        for x in lst:
            check(type(x) is int and 0 <= x <= cap - 1)
        res.append(list(lst))
        globals()['queries_total'] = globals().get('queries_total', 0) + len(lst)
    return res

# ---------------------------------------------------------------- semantics
class Session:
    def __init__(self, n, tcount, foots, doms, caps, groups, tasks):
        self.n = n
        self.tcount = tcount
        self.foots = foots
        self.doms = doms          # per template: domain value
        self.caps = list(caps)
        self.quota = [q for q, b in groups]
        self.budget = [b for q, b in groups]
        self.tasks = [dict(template=r[0], group=r[1], weight=r[2], class=r[3], pin=r[4]) for r in tasks]
        self.revision = 0

def group_state(s):
    """footprints, loads, counts and key sets of every group in state s."""
    members = [[] for _ in s.quota]
    for tid, t in enumerate(s.tasks):
        members[t['group']].append(tid)
    fp = []
    load = []
    keys = []
    for m in members:
        u = set()
        tot = 0
        ks = set()
        for tid in m:
            t = s.tasks[tid]
            u |= s.foots[t['template']]
            tot += t['weight']
            ks.add((s.doms[t['template']], t['class']))
        fp.append(u)
        load.append(tot)
        keys.append(ks)
    return members, fp, load, keys

def usage_of(s, fp):
    usage = [0] * s.n
    for gid, nodes in enumerate(fp):
        if nodes:
            for x in nodes:
                usage[x] += s.quota[gid]
    return usage

def counts(s, begin=None):
    members, fp, load, keys = group_state(s)
    usage = usage_of(s, fp)
    capacity = sum(1 for x in range(s.n) if usage[x] > s.caps[x])
    mixed = sum(1 for gid in range(len(s.quota)) if len(keys[gid]) > 1)
    work = 0
    for gid in range(len(s.quota)):
        if members[gid]:
            if s.quota[gid] == 0 or load[gid] > s.quota[gid] * s.budget[gid]:
                work += 1
    pins = 0
    if begin is not None:
        for tid in range(len(s.tasks)):
            b = begin[tid]
            if not b['pin']:
                continue
            t = s.tasks[tid]
            if (t['group'] != b['group'] or t['template'] != b['template']
                    or t['weight'] != b['weight'] or t['class'] != b['class']
                    or s.quota[b['group']] != begin_q[begin][0]):
                pins += 1
    return [capacity, mixed, work, pins], members, fp, load, keys, usage

def certificate(s, q, members, fp, load, keys, usage):
    totals = [sum(1 for gid in range(len(s.quota)) if members[gid]),
              sum(usage), sum(t['weight'] for t in s.tasks),
              sum(1 for t in s.tasks if t['pin'])]
    grows = []
    for gid in q[0]:
        if members[gid]:
            dom, cls = next(iter(keys[gid]))
        else:
            dom = cls = -1
        grows.append([gid, len(members[gid]), load[gid], s.quota[gid], s.budget[gid], len(fp[gid]), dom, cls])
    nrows = [[x, usage[x], s.caps[x]] for x in q[1]]
    trows = [[tid, s.tasks[tid]['group'], s.tasks[tid]['template'], s.tasks[tid]['weight'],
              s.tasks[tid]['class'], s.tasks[tid]['pin']] for tid in q[2]]
    return {'totals': totals, 'groups': grows, 'nodes': nrows, 'tasks': trows}

def snapshot(s):
    return [dict(t) for t in s.tasks]

def initial_illegal(s):
    members, fp, load, keys = group_state(s)
    for gid in range(len(s.quota)):
        if members[gid]:
            if len(keys[gid]) > 1 or s.quota[gid] == 0 or load[gid] > s.quota[gid] * s.budget[gid]:
                return True
    usage = usage_of(s, fp)
    return any(usage[x] > s.caps[x] for x in range(s.n))

def run(request):
    try:
        sessions = validate(request)
    except Invalid:
        return '{"error":"invalid"}'
    results = []
    for code, args, n, tcount, caps, groups, trows, q0, txs in sessions:
        n2, t2, foots, doms = topo_table(code, args)
        assert (n2, t2) == (n, tcount), (n2, t2, n, tcount)
        s = Session(n, tcount, foots, [d for pair in () for d in ()] or [0] * 0, caps, groups, trows)
        # domains from the dump tool: recompute via table
        s.doms = DOMAINS[(code, tuple(args))]
        if initial_illegal(s):
            return '{"error":"invalid"}'
        members, fp, load, keys = group_state(s)
        usage = usage_of(s, fp)
        cert0 = certificate(s, q0, members, fp, load, keys, usage)
        outs = []
        for revision, elist, tq in txs:
            if revision != s.revision:
                members, fp, load, keys = group_state(s)
                usage = usage_of(s, fp)
                outs.append({'accepted': False, 'revision': s.revision, 'violations': None,
                             'certificate': certificate(s, tq, members, fp, load, keys, usage)})
                continue
            begin = snapshot(s)
            begin_quota = list(s.quota)
            for op, idx, value in elist:
                if op == 'move': s.tasks[idx]['group'] = value
                elif op == 'weight': s.tasks[idx]['weight'] = value
                elif op == 'class': s.tasks[idx]['class'] = value
                elif op == 'bind': s.tasks[idx]['template'] = value
                elif op == 'pin': s.tasks[idx]['pin'] = value
                elif op == 'quota': s.quota[idx] = value
                elif op == 'budget': s.budget[idx] = value
                elif op == 'cap': s.caps[idx] = value
            propsal = s
            viol = proposal_counts(begin, begin_quota, propsal)
            accepted = all(v == 0 for v in viol)
            if accepted:
                s.revision += 1
            else:
                s.tasks = [dict(t) for t in begin]
                s.quota = list(begin_quota)
                s.budget = list(bud_save[0])
                s.caps = list(cap_save[0])
            members, fp, load, keys = group_state(s)
            usage = usage_of(s, fp)
            outs.append({'accepted': accepted, 'revision': s.revision, 'violations': viol,
                         'certificate': certificate(s, tq, members, fp, load, keys, usage)})
        results.append({'nodes': n, 'templates': tcount, 'initial': cert0, 'transactions': outs})
    return json.dumps({'sessions': results}, separators=(',', ':'))

DOMAINS = {}
bud_save = [None]
cap_save = [None]

def proposal_counts(begin, begin_quota, s):
    members, fp, load, keys = group_state(s)
    usage = usage_of(s, fp)
    capacity = sum(1 for x in range(s.n) if usage[x] > s.caps[x])
    mixed = sum(1 for gid in range(len(s.quota)) if len(keys[gid]) > 1)
    work = sum(1 for gid in range(len(s.quota))
               if members[gid] and (s.quota[gid] == 0 or load[gid] > s.quota[gid] * s.budget[gid]))
    pins = 0
    for tid in range(len(s.tasks)):
        b = begin[tid]
        if not b['pin']:
            continue
        t = s.tasks[tid]
        if (t['group'] != b['group'] or t['template'] != b['template'] or t['weight'] != b['weight']
                or t['class'] != b['class'] or s.quota[b['group']] != begin_quota[b['group']]):
            pins += 1
    return [capacity, mixed, work, pins]
